import { useState, useEffect, useCallback, useRef, useMemo } from "react";

// ═══════════════════════════════════════════════════════
//  AUDIO
// ═══════════════════════════════════════════════════════
function useAudio() {
  const ctx = useRef(null);
  const bgmOn = useRef(false);
  const gc = () => { if (!ctx.current) ctx.current = new (window.AudioContext || window.webkitAudioContext)(); return ctx.current; };
  const startBGM = useCallback(() => {
    if (bgmOn.current) return; bgmOn.current = true;
    try {
      const c = gc(), m = c.createGain(); m.gain.value = 0.1; m.connect(c.destination);
      [[180,.8,.06,.05],[320,1.2,.03,.04],[90,.5,.07,.03]].forEach(([f,q,g,s])=>{
        const b=c.createBuffer(1,c.sampleRate*3,c.sampleRate),d=b.getChannelData(0);
        for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;
        const src=c.createBufferSource(); src.buffer=b; src.loop=true;
        const fi=c.createBiquadFilter(); fi.type="bandpass"; fi.frequency.value=f; fi.Q.value=q;
        const gn=c.createGain(); gn.gain.value=g;
        const lfo=c.createOscillator(); lfo.frequency.value=s;
        const lg=c.createGain(); lg.gain.value=g*.3;
        lfo.connect(lg); lg.connect(gn.gain); src.connect(fi); fi.connect(gn); gn.connect(m); lfo.start(); src.start();
      });
      const ns=[261.6,329.6,392,493.9,523.2,659.3]; let ni=0;
      setInterval(()=>{ try {
        const o=c.createOscillator(),g=c.createGain(); o.type="sine"; o.frequency.value=ns[ni%ns.length]; ni++;
        const t=c.currentTime;
        g.gain.setValueAtTime(0,t); g.gain.linearRampToValueAtTime(0.04,t+.4); g.gain.exponentialRampToValueAtTime(0.001,t+3.2);
        o.connect(g); g.connect(m); o.start(t); o.stop(t+3.2);
      }catch{} },2800);
    }catch{}
  },[]);
  const sfx = useCallback((type,combo=1)=>{
    try{
      const c=gc(),t=c.currentTime;
      if(type==="coin"){
        const f=Math.min(380+combo*28,1000);
        const o=c.createOscillator(),g=c.createGain();
        o.type="sine"; o.frequency.setValueAtTime(f,t); o.frequency.exponentialRampToValueAtTime(f*1.5,t+.08);
        g.gain.setValueAtTime(0.18,t); g.gain.exponentialRampToValueAtTime(0.001,t+.22);
        o.connect(g); g.connect(c.destination); o.start(t); o.stop(t+.22);
      }
      if(type==="buy"||type==="heal"){
        [0,.1,.2].forEach((dt,i)=>{const o=c.createOscillator(),g=c.createGain();
          o.type="triangle"; o.frequency.value=[440,554,659][i];
          g.gain.setValueAtTime(0.12,t+dt); g.gain.exponentialRampToValueAtTime(0.001,t+dt+.22);
          o.connect(g); g.connect(c.destination); o.start(t+dt); o.stop(t+dt+.22);});
      }
      if(type==="attack"){
        const o=c.createOscillator(),g=c.createGain();
        o.type="sawtooth"; o.frequency.setValueAtTime(220,t); o.frequency.exponentialRampToValueAtTime(110,t+.15);
        g.gain.setValueAtTime(0.25,t); g.gain.exponentialRampToValueAtTime(0.001,t+.2);
        o.connect(g); g.connect(c.destination); o.start(t); o.stop(t+.2);
      }
      if(type==="skill"){
        [0,.06,.13,.22,.33].forEach((dt,i)=>{const o=c.createOscillator(),g=c.createGain();
          o.type=i<3?"sine":"triangle"; o.frequency.value=[392,494,587,784,988][i];
          g.gain.setValueAtTime(0.15,t+dt); g.gain.exponentialRampToValueAtTime(0.001,t+dt+.3);
          o.connect(g); g.connect(c.destination); o.start(t+dt); o.stop(t+dt+.3);});
      }
      if(type==="bosshit"){
        [0,.04,.09].forEach((dt,i)=>{const o=c.createOscillator(),g=c.createGain();
          o.type="sawtooth"; o.frequency.value=[180,140,100][i];
          g.gain.setValueAtTime(0.2,t+dt); g.gain.exponentialRampToValueAtTime(0.001,t+dt+.18);
          o.connect(g); g.connect(c.destination); o.start(t+dt); o.stop(t+dt+.18);});
      }
      if(type==="victory"){
        [0,.1,.2,.35,.5,.7].forEach((dt,i)=>{const o=c.createOscillator(),g=c.createGain();
          o.type="sine"; o.frequency.value=[523,659,784,1047,1319,1568][i];
          g.gain.setValueAtTime(0.18,t+dt); g.gain.exponentialRampToValueAtTime(0.001,t+dt+.45);
          o.connect(g); g.connect(c.destination); o.start(t+dt); o.stop(t+dt+.45);});
      }
      if(type==="gameover"){
        [0,.15,.35].forEach((dt,i)=>{const o=c.createOscillator(),g=c.createGain();
          o.type="sawtooth"; o.frequency.value=[220,185,147][i];
          g.gain.setValueAtTime(0.18,t+dt); g.gain.exponentialRampToValueAtTime(0.001,t+dt+.4);
          o.connect(g); g.connect(c.destination); o.start(t+dt); o.stop(t+dt+.4);});
      }
      if(type==="merge"){
        [0,.06,.14,.24].forEach((dt,i)=>{const o=c.createOscillator(),g=c.createGain();
          o.type="sine"; o.frequency.value=[523,659,784,1047][i];
          g.gain.setValueAtTime(0.16,t+dt); g.gain.exponentialRampToValueAtTime(0.001,t+dt+.28);
          o.connect(g); g.connect(c.destination); o.start(t+dt); o.stop(t+dt+.28);});
      }
    }catch{}
  },[]);
  return { startBGM, sfx };
}

