// ── キャラ名→SPRITES keyマッピング ──
const CHAR_KEYS = ['pukurin', 'hoshimi', 'kumosuke', 'fuwarin', 'drago', 'sukesuke', 'moony', 'universe', 'nijirin', 'fossil', 'devil', 'celestia'];

// ── FishImage: スプライトから描画 ──
function FishSVG({idx, p=0, sq=1, w=56, gl=false, lv=1}) {
  const key = CHAR_KEYS[idx];
  const lvKey = lv >= 3 ? 'lv3' : lv >= 2 ? 'lv2' : 'lv1';
  const src = SPRITES[key]?.[lvKey] || SPRITES[key]?.lv1;
  if (!src) return null;

  const glowCol = ['#FF88CC','#FFD700','#88CCFF','#BB88FF','#FF6644','#44FFEE','#FFE080','#9966FF','#FF88FF','#DDBB77','#FF2244','#FFFFFF'][idx] || '#FFFFFF';
  
  // sq でぽよぽよ感 (scaleY)
  const scaleY = sq;
  const scaleX = 1 + (1 - sq) * 0.4;
  
  return (
    <img
      src={src}
      alt={key}
      style={{
        width: w,
        height: 'auto',
        transform: `scaleX(${scaleX}) scaleY(${scaleY})`,
        filter: gl || lv >= 2
          ? `drop-shadow(0 0 ${lv===3?10:6}px ${glowCol}) brightness(${lv===3?1.15:lv===2?1.08:1})`
          : 'none',
        imageRendering: 'auto',
        pointerEvents: 'none',
      }}
    />
  );
}


