function getLv(fishExp, fishId) {
  if(!fishId)return 1;
  const e = fishExp[fishId];
  if (!e) return 1;
  if (e.exp >= EXP_TO_LV3) return 3;
  if (e.exp >= EXP_TO_LV2) return 2;
  return 1;
}
function getExp(fishExp, fishId) { return fishExp[fishId]?.exp || 0; }
function getExpToNext(lv) { return lv >= 3 ? null : lv === 2 ? EXP_TO_LV3 : EXP_TO_LV2; }
function getExpPct(fishExp, fishId) {
  const exp = getExp(fishExp, fishId);
  const lv = getLv(fishExp, fishId);
  if (lv >= 3) return 100;
  const base = lv === 2 ? EXP_TO_LV2 : 0;
  const next = lv === 2 ? EXP_TO_LV3 : EXP_TO_LV2;
  return Math.min(100, ((exp - base) / (next - base)) * 100);
}

