const fp=(base,cnt)=>Math.ceil(base*Math.pow(1.18,cnt));
const fmt=n=>{
  if(n>=1e16)return(n/1e16).toFixed(2)+"京";
  if(n>=1e12)return(n/1e12).toFixed(2)+"兆";
  if(n>=1e8) return(n/1e8).toFixed(2)+"億";
  if(n>=1e4) return(n/1e4).toFixed(1)+"万";
  return Math.floor(n).toLocaleString();
};
const isNight=()=>{const h=new Date().getHours();return h>=18||h<6;};

// ガチャ累計回数による解放制度
const GACHA_UNLOCK = [
  {need:0,  fish:[0,1,2]},       // 最初: コモン3種
  {need:10, fish:[3,4,5]},       // 10連: レア解放
  {need:30, fish:[6,7,8]},       // 30連: エピック解放
  {need:60, fish:[9,10,11]},     // 60連: レジェンダリー解放
];
// 解放済みプールを取得
function getUnlockedPool(totalPulls) {
  let unlocked = [];
  for (const u of GACHA_UNLOCK) {
    if (totalPulls >= u.need) unlocked.push(...u.fish);
  }
  return unlocked;
}
// 重みテーブル (レアリティ別)
const WEIGHT = {common:30, rare:12, epic:5, legendary:1.5};

function drawGacha(pity, totalPulls) {
  const pool = getUnlockedPool(totalPulls);
  // 天井: 解放済みの最高レアを確定
  if (pity >= 100) {
    const legendary = pool.filter(fi => FISH[fi]?.rarity === 'legendary');
    const epic      = pool.filter(fi => FISH[fi]?.rarity === 'epic');
    if (legendary.length) return legendary[Math.floor(Math.random()*legendary.length)];
    if (epic.length)      return epic[Math.floor(Math.random()*epic.length)];
    return pool[pool.length-1];
  }
  // 50連ハーフ保証: epic以上
  if (pity >= 50) {
    const high = pool.filter(fi => ['epic','legendary'].includes(FISH[fi]?.rarity));
    if (high.length) {
      const tw = high.length; let r = Math.random()*tw;
      for (const fi of high) { r--; if(r<=0) return fi; }
      return high[0];
    }
  }
  // 通常抽選
  const weighted = pool.map(fi => [fi, WEIGHT[FISH[fi]?.rarity]||1]);
  const tw = weighted.reduce((a,[,w])=>a+w, 0);
  let r = Math.random()*tw;
  for (const [fi,w] of weighted) { r-=w; if(r<=0) return fi; }
  return pool[0];
}

const SAVE_KEY="aqua_rpg_v1";
const saveGame=s=>{try{localStorage.setItem(SAVE_KEY,JSON.stringify({...s,savedAt:Date.now()}));}catch{}};
