// ─── Ranking ─────────────────────────────────────────────
async function submitScore(name,score){
  try{await window.storage.set("rank:"+name,JSON.stringify({name,score,at:Date.now()}),true);return true;}catch{return false;}
}
async function fetchRanking(){
  try{
    const res=await window.storage.list("rank:",true);
    if(!res||!res.keys)return[];
    const entries=await Promise.all(res.keys.map(async k=>{
      try{const r=await window.storage.get(k,true);return r?JSON.parse(r.value):null;}catch{return null;}
    }));
    return entries.filter(Boolean).sort((a,b)=>b.score-a.score).slice(0,20);
  }catch{return[];}
}

// ═══════════════════════════════════════════════════════
//  BATTLE SYSTEM
// ═══════════════════════════════════════════════════════
function calcATK(slots,upgs,prestigeMult){
  // ATK = 各スロットの魚の収入 × Lvボーナス × 強化倍率 の合計 × 0.5
  return Math.max(10, slots.reduce((acc,sl)=>{
    const f=FISH[sl.fi];
    const fm=UPGRADES.filter(u=>u.fi===sl.fi&&upgs[u.id]).reduce((a,u)=>a*u.mult,1);
    const lvM=sl.lv===3?4:sl.lv===2?2:1;
    return acc+(f?.inc||0)*fm*lvM;
  },0)*prestigeMult*0.5);
}

