// ═══════════════════════════════════════════════════════
//  SWIM FISH
// ═══════════════════════════════════════════════════════
function SwimFish({fi,ix,iy,fw,gl,lv=1}){
  const r=useRef({x:ix,y:iy,p:Math.random()*Math.PI*2,sq:1,dir:Math.random()>.5?1:-1,
    spd:.07+Math.random()*.09,vert:(Math.random()-.5)*.045,bounce:0,fr:0});
  const[st,setSt]=useState({x:ix,y:iy,p:0,sq:1,dir:r.current.dir});
  useEffect(()=>{
    let raf;
    const tick=()=>{
      const v=r.current;v.p+=.058;v.bounce+=.088;v.sq=.91+Math.sin(v.bounce)*.09;
      v.x+=v.spd*v.dir;v.y+=Math.sin(v.p*.8)*.38+v.vert;
      if(v.x>85){v.x=85;v.dir=-1;}if(v.x<3){v.x=3;v.dir=1;}
      if(v.y>67){v.y=67;v.vert*=-1;}if(v.y<3){v.y=3;v.vert*=-1;}
      if(Math.random()<.003)v.dir*=-1;
      v.fr++;if(v.fr%2===0)setSt({x:v.x,y:v.y,p:v.p,sq:v.sq,dir:v.dir});
      raf=requestAnimationFrame(tick);
    };
    raf=requestAnimationFrame(tick);return()=>cancelAnimationFrame(raf);
  },[]);
  const f=FISH[fi];
  return <div style={{position:"absolute",left:st.x+"%",top:st.y+"%",transform:`scaleX(${st.dir===-1?-1:1})`,filter:`drop-shadow(0 4px 10px ${f?.glow||'#FFFFFF'}${gl||lv>=2?"bb":"55"})`,pointerEvents:"none",transition:"transform .2s",willChange:"left,top"}}>
    <FishSVG idx={fi} p={st.p} sq={st.sq} w={fw} gl={gl||lv>=2} lv={lv}/>
  </div>;
}

