function Ripple({x,y,id,onDone,color="#4DF"}){
  useEffect(()=>{const t=setTimeout(()=>onDone(id),700);return()=>clearTimeout(t);},[id,onDone]);
  return <div style={{position:"fixed",left:x,top:y,pointerEvents:"none",zIndex:8000,transform:"translate(-50%,-50%)"}}>
    <div style={{width:64,height:64,borderRadius:"50%",border:`2.5px solid ${color}`,animation:"ripOut .7s ease-out forwards"}}/>
  </div>;
}
function CoinPop({x,y,id,txt,combo,onDone}){
  useEffect(()=>{const t=setTimeout(()=>onDone(id),1000);return()=>clearTimeout(t);},[id,onDone]);
  const col=combo>=20?"#FF5522":combo>=10?"#FFD700":combo>=5?"#AAFFEE":"#FFF";
  return <div style={{position:"fixed",left:x-24,top:y-32,pointerEvents:"none",zIndex:9000,fontFamily:"'Nunito',sans-serif",fontWeight:900,fontSize:combo>=5?20:15,color:col,textShadow:`0 0 12px ${col},0 2px 8px rgba(0,0,0,.9)`,animation:"coinUp 1s ease-out forwards",whiteSpace:"nowrap"}}>
    {combo>=5&&<span style={{fontSize:10,opacity:.85,marginRight:2}}>×{combo}</span>}{txt}
  </div>;
}
function Toast({msg,onDone}){
  useEffect(()=>{const t=setTimeout(onDone,3000);return()=>clearTimeout(t);},[onDone]);
  return <div style={{position:"fixed",bottom:92,left:"50%",transform:"translateX(-50%)",background:"linear-gradient(135deg,rgba(10,20,60,.96),rgba(20,40,100,.97))",border:"1.5px solid rgba(100,180,255,.35)",borderRadius:18,padding:"10px 22px",zIndex:9999,fontFamily:"'Nunito',sans-serif",fontWeight:800,fontSize:13,color:"white",boxShadow:"0 8px 40px rgba(0,0,0,.7)",animation:"toastIn .35s ease-out",whiteSpace:"nowrap"}}>{msg}</div>;
}

